export function HoverCard({
  title = "{{title}}",
  style = "{{style}}",
  hovered = {{hovered}},
  accent = "{{accent}}",
}) {
  const active = {
    lift: { transform: "translateY(-4px)", boxShadow: "0 14px 26px rgba(36,20,48,.18)" },
    glow: { boxShadow: "0 0 0 4px " + accent },
    border: { borderColor: accent },
  }[style];
  return (
    <div style={{ width: 220, fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430" }}>
      <div style={{ borderRadius: 12, padding: 14, background: "#FAF7F2", border: "1.5px solid #24143022", transition: "transform .15s, box-shadow .15s, border-color .15s", ...(hovered ? active : {}) }}>
        <div style={{ height: 80, borderRadius: 8, background: "#24143014", marginBottom: 10 }} />
        <p style={{ margin: 0, fontWeight: 600, fontSize: 13 }}>{title}</p>
      </div>
      <p style={{ marginTop: 10, fontSize: 12, color: "#241430aa" }}>{hovered ? "shown as if the pointer is over the card" : "rest state \u2014 move your pointer over it"}</p>
    </div>
  );
}
